/* Flat by default */
.card { rotate: 0deg; }

/* Only where random() exists */
@supports (rotate: random(-2deg, 2deg)) {
  @media (prefers-reduced-motion: no-preference) {
    .card {
      rotate: random(-2deg, 2deg);
      /* step of 2px keeps offsets on your grid */
      translate: 0 random(-4px, 4px, by 2px);
    }
  }
}

/* Shared key: width and height get the same value */
.tile {
  width: random(--tile-size, 48px, 96px, by 8px);
  height: random(--tile-size, 48px, 96px, by 8px);
}
